package de.elbracht.smp.servers;
import com.fasterxml.jackson.databind.ObjectMapper;
import java.net.URI;
import java.time.Instant;
import java.util.*;
import org.junit.jupiter.api.*;
import static org.assertj.core.api.Assertions.*;
import static org.mockito.Mockito.*;
class ModImportTest {
 final ObjectMapper mapper=new ObjectMapper();HostAgent agent;ModCatalog catalog;ModManagementService service;
 @BeforeEach void setup(){agent=mock(HostAgent.class);catalog=mock(ModCatalog.class);when(agent.modsAvailable()).thenReturn(true);service=new ModManagementService(agent,catalog,mapper);}
 void state(Map<String,String> files){var state=new ModManagementService.State(false,"a".repeat(64),new ModManagementService.Manifest(1,List.of(),List.of()),files,"MANUAL_MODS_REQUIRE_IMPORT");when(agent.modRpc(eq("main"),eq("/mods/state"),eq("GET"),isNull(),any())).thenReturn(mapper.valueToTree(state));}
 ModCatalog.Bundle bundle(String hash){var pin=new CurseForgePlanResolver.Pinned(1,2,"Explicit metadata fixture",20,"c".repeat(40),URI.create("https://edge.forgecdn.net/files/1/2/fixture.jar"),List.of(),List.of(),List.of());return new ModCatalog.Bundle("26.3","0.19.5","25.0.4.1",List.of(new ModCatalog.Root(1,2)),List.of(new ModCatalog.Artifact(pin,hash,"explicit-unit-fixture-content")));}
 @Test void partialAndDuplicateAssignmentsNeverDownloadAnything(){state(Map.of("manual.jar","b".repeat(64),"other.jar","d".repeat(64)));assertThatThrownBy(()->service.prepareImport("main",List.of(new ModManagementService.Assignment("manual.jar",1,2)))).isInstanceOf(de.elbracht.smp.api.ApiException.class);assertThatThrownBy(()->service.prepareImport("main",List.of(new ModManagementService.Assignment("manual.jar",1,2),new ModManagementService.Assignment("other.jar",1,2)))).isInstanceOf(de.elbracht.smp.api.ApiException.class);verifyNoInteractions(catalog);}
 @Test void mismatchedBytesNeverCreateAnAgentPlan(){state(Map.of("manual.jar","b".repeat(64)));when(catalog.downloadBundle(eq("main"),anyList())).thenReturn(bundle("d".repeat(64)));assertThatThrownBy(()->service.prepareImport("main",List.of(new ModManagementService.Assignment("manual.jar",1,2)))).isInstanceOf(de.elbracht.smp.api.ApiException.class);verify(agent,never()).modRpc(eq("main"),eq("/mods/plans"),eq("POST"),anyMap(),any());}
 @Test void exactImportCarriesCompleteAssignmentsAndRevisionWithoutExposingPackages(){state(Map.of("manual.jar","b".repeat(64)));when(catalog.downloadBundle(eq("main"),anyList())).thenReturn(bundle("b".repeat(64)));UUID id=UUID.randomUUID();var plan=new ModManagementService.Plan(id,Instant.now().toString(),Instant.now().plusSeconds(900).toString(),"26.3","0.19.5","25.0.4.1",List.of(new ModManagementService.Pin(1,2,20,"b".repeat(64),"c".repeat(40),List.of(),"CURSEFORGE")),List.of("Explicit import unit fixture"),"PLANNED");when(agent.modRpc(eq("main"),eq("/mods/plans"),eq("POST"),anyMap(),any())).thenAnswer(call->{Map<String,Object> body=call.getArgument(3);assertThat(body.get("imports")).isEqualTo(Map.of("manual.jar",1L));assertThat(body.get("revision")).isEqualTo("a".repeat(64));assertThat(body.get("roots")).isEqualTo(List.of(new ModCatalog.Root(1,2)));return mapper.valueToTree(plan);});assertThat(service.prepareImport("main",List.of(new ModManagementService.Assignment("manual.jar",1,2))).planId()).isEqualTo(id);}
 @Test void contradictoryAgentManifestNeverBecomesAConfirmablePlan(){state(Map.of("manual.jar","b".repeat(64)));when(catalog.downloadBundle(eq("main"),anyList())).thenReturn(bundle("b".repeat(64)));var wrong=new ModManagementService.Plan(UUID.randomUUID(),Instant.now().toString(),Instant.now().plusSeconds(900).toString(),"26.3","0.19.5","25.0.4.1",List.of(),List.of("Contradictory explicit fixture"),"PLANNED");when(agent.modRpc(eq("main"),eq("/mods/plans"),eq("POST"),anyMap(),any())).thenReturn(mapper.valueToTree(wrong));assertThatThrownBy(()->service.prepareImport("main",List.of(new ModManagementService.Assignment("manual.jar",1,2)))).isInstanceOf(de.elbracht.smp.api.ApiException.class);}
}

